def _creer_lots_historiques(apps, schema_editor):
    """Stock déjà présent dans une pharmacie avant ce suivi par lot : on ne
    connaît ni son origine ni sa date de péremption, donc un lot générique
    « HISTORIQUE » par produit (jamais bloqué par le contrôle de péremption,
    comme tout lot sans date connue) — juste pour que la somme des lots
    reste égale à StockPharmacie.quantite dès le départ."""
    StockPharmacie = apps.get_model('pharmacie', 'StockPharmacie')
    LotPharmacie = apps.get_model('pharmacie', 'LotPharmacie')
    for sp in StockPharmacie.objects.filter(quantite__gt=0):
        LotPharmacie.objects.create(
            pharmacie=sp.pharmacie, produit_id=sp.produit_id,
            numero_lot='HISTORIQUE', quantite_actuelle=sp.quantite,
        )


